{
  "bioavailability_prediction": "high",
  "confidence": "high",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C06","C23","C147","C109","C106","C76","C85","C97","C148","C151","C183","C184","C191","C202","C226","C239"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C06","C23","C147","C109","C106","C76","C85","C97","C148","C151","C183","C184","C191","C202","C226","C239"],
  "claims": [
    {
      "claim": "The closest L1 analog with direct absolute oral bioavailability evidence, imipramine-N-oxide, showed 100% systemic availability after oral dosing versus IV in healthy volunteers, supporting high oral bioavailability in the tricyclic dibenzoazepine series.",
      "card_ids": ["C06","C23"]
    },
    {
      "claim": "L4 records for the close analog oxcarbazepine show essentially complete absorption after a single oral radiolabeled dose in humans (C147), almost complete absorption after oral tablets (C109), and classification as highly permeable in mouse jejunum Ussing-chamber studies (C106).",
      "card_ids": ["C147","C109","C106"]
    },
    {
      "claim": "L3 records after oral carbamazepine dosing show measurable systemic exposure of its metabolite carbamazepine-10,11-epoxide: AUC0-120 120.7 µmol·h/L after a single 200 mg oral dose (C76), Cmax 2.1 µmol/L (C85), and AUC12 9.98 µg·h/mL at steady state (C97), consistent with oral absorption of carbamazepine.",
      "card_ids": ["C76","C85","C97"]
    },
    {
      "claim": "L5 Caco-2 bidirectional data for the tricyclic analog imipramine show Papp A-B 10.8 × 10^-6 cm/s, Papp B-A 12.1 × 10^-6 cm/s, efflux ratio 1.1 (C148, C151, C184), high absorption (C183), and no change in P-gp-mediated efflux with taurocholate (C191), indicating no significant gut-wall efflux in this scaffold.",
      "card_ids": ["C148","C151","C183","C184","C191"]
    },
    {
      "claim": "L6 hepatic evidence for carbamazepine itself is limited but not indicative of extensive first-pass loss: cimetidine increased carbamazepine and its 10,11-epoxide half-life by only 10–20% in humans (C202), and isolated perfused rat liver intrinsic formation clearance of carbamazepine-10,11-epoxide was about 6 ml/min (C226, C239).",
      "card_ids": ["C202","C226","C239"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C202","C226","C239"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability (oral vs IV) measurement for carbamazepine is present in the supplied records.",
    "L6 hepatic clearance records for carbamazepine are limited to epoxide formation and half-life modulation; no human intrinsic clearance or hepatic extraction fraction for carbamazepine is supplied.",
    "Most L6 records are for oxcarbazepine/MHD or other tricyclics and are not directly transferable to carbamazepine.",
    "L3 exposure records lack IV comparators, so they inform absorption but do not quantify F.",
    "Some L1/L2 contexts are from cirrhosis or fed conditions and may not match a general healthy adult oral condition."
  ],
  "decision_summary": "Predicted high: direct L1 analog imipramine-N-oxide had 100% oral systemic availability (C06, C23); L4 oxcarbazepine records show essentially complete absorption and high permeability (C147, C109, C106); L3 oral carbamazepine exposure records show measurable systemic metabolite exposure (C76, C85, C97); L5 imipramine gut-wall data show no significant efflux (C148, C151, C183, C184, C191); L6 hepatic evidence shows only moderate carbamazepine metabolism (C202, C226, C239). No affirmative threshold-relevant evidence supports F < 20%."
}

